// ════════════════════════════════════════
//  PORTUGAIS EUROPÉEN (Portugal) — niveaux B1 & B2
// ════════════════════════════════════════
(() => {
const { G, I, C, F, T, O, W, L, D, lesson, unit, course } = LS;

course('pt', { flag: '🇵🇹', name: 'Portugais', nameFr: 'Português (Portugal)', tts: 'pt-PT' }, [

// ─────────────── B1 ───────────────
unit('pt_b1_1', 'B1', 'A saúde', 'La santé', '🩺', '#ef4444', [
  lesson('No médico', 'Chez le médecin',
    G('« Doer » : dire où on a mal',
      `<b>doer</b> fonctionne comme « plaire » : c\'est la partie du corps qui est le sujet.<br><b>Dói-me</b> a cabeça (singulier) = j\'ai mal à la tête.<br><b>Doem-me</b> as costas (pluriel) = j\'ai mal au dos.<br>Autres : <b>Tenho febre</b> (de la fièvre), <b>Tenho tosse</b> (je tousse), <b>Estou constipado/a</b> (je suis enrhumé·e !), <b>Estou enjoado/a</b> (j\'ai la nausée).<br>Conseil : <b>Deve</b> + infinitif (vous devriez).`,
      [['Dói-me muito a garganta.', 'J\'ai très mal à la gorge.'], ['Doem-me os pés.', 'J\'ai mal aux pieds.'], ['Deve descansar e beber muita água.', 'Vous devez vous reposer et boire beaucoup d\'eau.']],
      'FAUX AMI : « constipado » = enrhumé, pas constipé ! Constipé se dit « com prisão de ventre ».'),
    [
      I('Dói-me…', 'J\'ai mal à…', 'Dói-me o estômago.', 'J\'ai mal à l\'estomac.'),
      I('Estou constipado/a', 'Je suis enrhumé(e)', 'Estou constipada desde segunda.', 'Je suis enrhumée depuis lundi.'),
      I('a febre / a tosse', 'la fièvre / la toux', 'Tem febre?', 'Vous avez de la fièvre ?'),
      I('a receita', 'l\'ordonnance', 'Vou passar-lhe uma receita.', 'Je vais vous faire une ordonnance.'),
      D('No centro de saúde', [
        ['Médica', 'Bom dia. Então, o que se passa?', 'Bonjour. Alors, qu\'est-ce qui ne va pas ?'],
        ['Paciente', 'Dói-me a garganta e tenho muita tosse. Estou muito cansado.', 'J\'ai mal à la gorge et je tousse beaucoup. Je suis très fatigué.'],
        ['Médica', 'Tem febre?', 'Vous avez de la fièvre ?'],
        ['Paciente', 'Tive trinta e oito e meio ontem à noite.', 'J\'avais 38,5 hier soir.'],
        ['Médica', 'Deve ser um vírus. Deve ficar em casa dois dias e beber muitos líquidos.', 'Ça doit être un virus. Restez chez vous deux jours et buvez beaucoup.'],
      ], [
        ['Quels sont les symptômes ?', ['Mal de gorge, toux, fatigue', 'Mal de dos', 'Mal au ventre', 'Mal aux dents']],
        ['Que conseille la médecin ?', ['Rester à la maison et boire', 'Faire du sport', 'Aller à l\'hôpital', 'Prendre des antibiotiques']],
      ]),
      F('___-me as costas.', ['Doem', 'Dói', 'Doi', 'Doe'], 'J\'ai mal au dos.', '« as costas » est pluriel → doem.'),
      F('___-me a cabeça.', ['Dói', 'Doem', 'Tenho', 'Estou'], 'J\'ai mal à la tête.'),
      C('« Estou constipado » signifie :', ['Je suis enrhumé', 'Je suis constipé', 'Je suis fatigué', 'Je suis stressé']),
      O('Vous devez vous reposer.', 'Deve descansar', ['tem']),
      W('J\'ai de la fièvre.', 'Tenho febre|Eu tenho febre'),
      L('Dói-me o joelho quando ando.', 'J\'ai mal au genou quand je marche.'),
      T('Que dois-je faire ?', ['O que devo fazer?', 'O que tenho fazer?', 'Que devo de fazer eu?', 'O que deve-me fazer?']),
    ]),

  lesson('Na farmácia', 'À la pharmacie',
    G('L\'obligation : ter de / dever / não é preciso',
      `<b>ter de</b> + infinitif = devoir (obligation forte) : <b>Tem de</b> tomar isto com comida.<br><b>dever</b> + infinitif = devoir (conseil) : <b>Deve</b> descansar.<br><b>não pode</b> = interdiction : <b>Não pode</b> beber álcool.<br><b>não é preciso</b> = pas besoin : <b>Não é preciso</b> receita.<br>Passé : <b>tive de</b> esperar (j\'ai dû attendre).`,
      [['Tenho de ir à farmácia.', 'Je dois aller à la pharmacie.'], ['Não é preciso marcar.', 'Pas besoin de réserver.'], ['Tive de esperar duas horas.', 'J\'ai dû attendre deux heures.']],
      'Au Portugal on dit « ter de » ; au Brésil plutôt « ter que ». Les deux sont compris.'),
    [
      I('ter de', 'devoir (obligation)', 'Tenho de trabalhar amanhã.', 'Je dois travailler demain.'),
      I('não é preciso', 'ce n\'est pas nécessaire', 'Não é preciso pagar.', 'Pas besoin de payer.'),
      I('o comprimido', 'le comprimé', 'Tome um comprimido de oito em oito horas.', 'Prenez un comprimé toutes les huit heures.'),
      I('em jejum', 'à jeun', 'Deve tomar em jejum.', 'À prendre à jeun.'),
      D('Na farmácia', [
        ['Farmacêutica', 'Boa tarde. Em que posso ajudar?', 'Bonjour. Je peux vous aider ?'],
        ['Cliente', 'Tenho esta receita. Tenho de tomar os comprimidos com comida?', 'J\'ai cette ordonnance. Je dois prendre les comprimés en mangeant ?'],
        ['Farmacêutica', 'Sim, tem de os tomar depois das refeições. E não pode beber álcool.', 'Oui, à prendre après les repas. Et pas d\'alcool.'],
        ['Cliente', 'Tenho de acabar a caixa?', 'Je dois finir la boîte ?'],
        ['Farmacêutica', 'Tem, mesmo que se sinta melhor.', 'Oui, même si vous vous sentez mieux.'],
      ], [
        ['Quand prendre les comprimés ?', ['Après les repas', 'Avant les repas', 'À jeun', 'Le soir seulement']],
        ['Qu\'est-ce qui est interdit ?', ['L\'alcool', 'Le café', 'Le sport', 'Le lait']],
      ]),
      F('Tenho ___ ir ao médico.', ['de', 'a', 'que de', 'para'], 'Je dois aller chez le médecin.'),
      F('Não é ___ marcar consulta.', ['preciso', 'precisa', 'necessário de', 'obrigado'], 'Pas besoin de prendre rendez-vous.'),
      C('« J\'ai dû attendre » :', ['Tive de esperar.', 'Tenho de esperei.', 'Tinha de esperado.', 'Devi de esperar.']),
      O('Vous ne pouvez pas boire d\'alcool.', 'Não pode beber álcool', ['deve']),
      W('Je dois aller à la pharmacie.', 'Tenho de ir à farmácia|Eu tenho de ir à farmácia|Tenho que ir à farmácia|Preciso de ir à farmácia'),
      L('Tome um comprimido de oito em oito horas.', 'Prenez un comprimé toutes les huit heures.'),
      T('Pas besoin d\'ordonnance.', ['Não é preciso receita.', 'Não precisa-se receita.', 'Não é preciso de receita.', 'Não tem de receita.']),
    ]),

  lesson('Comparar', 'Comparer',
    G('Comparatifs et superlatifs',
      `Supériorité : <b>mais</b> … <b>(do) que</b> : mais barato do que… Irréguliers :<br><b>bom → melhor</b> · <b>mau → pior</b> · <b>grande → maior</b> · <b>pequeno → menor</b> (ou mais pequeno, très courant au Portugal).<br>Infériorité : <b>menos</b> … <b>do que</b>. Égalité : <b>tão</b> … <b>como</b> / <b>tanto/a</b> … <b>como</b>.<br>Superlatif : <b>o/a mais</b> … <b>de</b> : a praia mais bonita <b>de</b> Portugal. Absolu : -<b>íssimo</b> : lindíssimo, caríssimo.`,
      [['O comboio é mais rápido do que o autocarro.', 'Le train est plus rapide que le bus.'], ['Este é o melhor restaurante da cidade.', 'C\'est le meilleur restaurant de la ville.'], ['Não está tão calor como ontem.', 'Il ne fait pas aussi chaud qu\'hier.']],
      '« Mais grande » est fautif : on dit « maior ». Mais « mais pequeno » est tout à fait correct au Portugal.'),
    [
      I('melhor / pior', 'meilleur(e) / pire', 'Este café é melhor.', 'Ce café est meilleur.'),
      I('maior / mais pequeno', 'plus grand / plus petit', 'O Porto é mais pequeno do que Lisboa.', 'Porto est plus petit que Lisbonne.'),
      I('tão … como', 'aussi … que', 'Ele é tão alto como o pai.', 'Il est aussi grand que son père.'),
      I('-íssimo', 'très, extrêmement', 'A vista é lindíssima!', 'La vue est magnifique !'),
      D('Escolher um ginásio (choisir une salle de sport)', [
        ['Ana', 'Qual é o melhor ginásio: o FitLife ou o Body Club?', 'Quelle est la meilleure salle : FitLife ou Body Club ?'],
        ['Rui', 'O FitLife é mais barato, mas o Body Club é maior e mais limpo.', 'FitLife est moins chère, mais Body Club est plus grande et plus propre.'],
        ['Ana', 'O Body Club é muito mais caro?', 'Body Club est beaucoup plus chère ?'],
        ['Rui', 'Dez euros a mais por mês. Mas tem a melhor piscina da cidade.', 'Dix euros de plus par mois. Mais elle a la meilleure piscine de la ville.'],
      ], [
        ['Quelle salle est la moins chère ?', ['FitLife', 'Body Club', 'Même prix', 'On ne sait pas']],
        ['Avantage de Body Club ?', ['La meilleure piscine', 'Ouverte 24 h/24', 'Gratuite', 'Des cours de yoga']],
      ]),
      F('Lisboa é ___ do que o Porto.', ['maior', 'mais grande', 'mais maior', 'grandíssimo'], 'Lisbonne est plus grande que Porto.'),
      F('É a praia mais bonita ___ Algarve.', ['do', 'de', 'que o', 'no'], 'C\'est la plus belle plage de l\'Algarve.'),
      C('Comparatif de « mau » :', ['pior', 'mais mau', 'piór', 'menor']),
      O('Le train est plus confortable que l\'avion.', 'O comboio é mais confortável do que o avião', ['tão']),
      W('C\'est le meilleur hôtel de la ville.', 'É o melhor hotel da cidade|Este é o melhor hotel da cidade'),
      L('O meu novo trabalho é muito melhor do que o antigo.', 'Mon nouveau travail est bien meilleur que l\'ancien.'),
      T('Ce n\'est pas aussi cher que je pensais.', ['Não é tão caro como eu pensava.', 'Não é tão caro do que pensava.', 'Não é tanto caro como pensava.', 'Não é mais caro como pensava.']),
    ]),
]),

unit('pt_b1_2', 'B1', 'Experiências', 'Expériences de vie', '🌍', '#3b82f6', [
  lesson('Quando era pequeno…', 'Quand j\'étais petit…',
    G('L\'imparfait (pretérito imperfeito)',
      `Pour les <b>habitudes passées</b> et les <b>descriptions</b> (comme l\'imparfait français).<br><b>-AR</b> : fal<b>ava</b>, fal<b>avas</b>, fal<b>ava</b>, fal<b>ávamos</b>, fal<b>avam</b><br><b>-ER / -IR</b> : com<b>ia</b>, com<b>ias</b>, com<b>ia</b>, com<b>íamos</b>, com<b>iam</b><br>Irréguliers : <b>ser</b> → era · <b>ter</b> → tinha · <b>vir</b> → vinha · <b>pôr</b> → punha.`,
      [['Quando era pequena, morava no campo.', 'Quand j\'étais petite, j\'habitais à la campagne.'], ['Todos os verões íamos para a praia.', 'Tous les étés nous allions à la plage.'], ['A casa tinha um jardim enorme.', 'La maison avait un immense jardin.']],
      'À l\'oral, l\'imparfait remplace souvent le conditionnel : « Queria um café » (je voudrais), « Se pudesse, ia » (si je pouvais, j\'irais).'),
    [
      I('quando era pequeno/a', 'quand j\'étais petit(e)', 'Quando era pequeno, tinha um cão.', 'Quand j\'étais petit, j\'avais un chien.'),
      I('costumava…', 'j\'avais l\'habitude de…', 'Costumava ir à pesca com o meu avô.', 'J\'allais souvent pêcher avec mon grand-père.'),
      I('antigamente', 'autrefois', 'Antigamente não havia turistas aqui.', 'Autrefois il n\'y avait pas de touristes ici.'),
      I('a infância', 'l\'enfance', 'Tive uma infância feliz.', 'J\'ai eu une enfance heureuse.'),
      D('Memórias de infância', [
        ['Neta', 'Avó, como era a vida quando eras nova?', 'Mamie, comment était la vie quand tu étais jeune ?'],
        ['Avó', 'Era muito diferente. Morávamos numa aldeia e não havia televisão.', 'Très différente. On vivait dans un village et il n\'y avait pas de télé.'],
        ['Neta', 'E o que faziam à noite?', 'Et que faisiez-vous le soir ?'],
        ['Avó', 'Conversávamos, cantávamos… e o meu pai contava histórias.', 'On discutait, on chantait… et mon père racontait des histoires.'],
      ], [
        ['Où vivait la grand-mère ?', ['Dans un village', 'À Lisbonne', 'Au bord de la mer', 'À l\'étranger']],
        ['Que faisait son père le soir ?', ['Il racontait des histoires', 'Il regardait la télé', 'Il travaillait', 'Il cuisinait']],
      ]),
      F('Quando eu ___ criança, vivia em Faro.', ['era', 'fui', 'estava', 'sou'], 'Quand j\'étais enfant, je vivais à Faro.'),
      F('Nós ___ sempre à praia no verão.', ['íamos', 'fomos', 'vamos', 'iamos-nos'], 'Nous allions toujours à la plage l\'été.'),
      C('« La maison avait trois chambres » :', ['A casa tinha três quartos.', 'A casa teve três quartos.', 'A casa tem três quartos antes.', 'A casa havia três quartos.']),
      O('Autrefois il n\'y avait pas de touristes.', 'Antigamente não havia turistas', ['houve']),
      W('Quand j\'étais petit(e), j\'avais un chat.', 'Quando era pequeno, tinha um gato|Quando era pequena, tinha um gato|Quando eu era pequeno, tinha um gato|Quando eu era pequena, tinha um gato|Quando era pequeno tinha um gato|Quando era pequena tinha um gato'),
      L('Todos os domingos almoçávamos em casa dos meus avós.', 'Tous les dimanches nous déjeunions chez mes grands-parents.'),
      T('Il faisait beau et les enfants jouaient.', ['Estava sol e as crianças brincavam.', 'Esteve sol e as crianças brincaram.', 'Fazia sol e as crianças jogavam.', 'Era sol e as crianças brincavam.']),
    ]),

  lesson('Perfeito ou imperfeito?', 'Passé simple ou imparfait ?',
    G('Pretérito perfeito vs imperfeito',
      `<b>Imperfeito</b> = le décor, ce qui était en cours, l\'habitude : Chovia. Eu <b>estava a dormir</b>.<br><b>Perfeito</b> = l\'action ponctuelle, terminée, qui fait avancer l\'histoire : O telefone <b>tocou</b>.<br>→ <b>Estava a dormir quando o telefone tocou.</b><br>C\'est exactement la logique imparfait / passé composé du français.`,
      [['Quando cheguei, estava a chover.', 'Quand je suis arrivé, il pleuvait.'], ['Enquanto jantávamos, a luz foi abaixo.', 'Pendant qu\'on dînait, il y a eu une coupure de courant.'], ['Era tarde quando saímos.', 'Il était tard quand nous sommes sortis.']],
      'Action en cours au passé : « estava a + infinitif » (= j\'étais en train de).'),
    [
      I('enquanto', 'pendant que', 'Enquanto eu cozinhava, ele pôs a mesa.', 'Pendant que je cuisinais, il a mis la table.'),
      I('de repente', 'soudain', 'De repente, começou a chover.', 'Soudain, il a commencé à pleuvoir.'),
      I('acontecer', 'arriver, se passer', 'O que aconteceu?', 'Que s\'est-il passé ?'),
      I('afinal', 'finalement, en fin de compte', 'Afinal, correu tudo bem.', 'Finalement, tout s\'est bien passé.'),
      D('Uma noite estranha', [
        ['Max', 'Então, o que aconteceu?', 'Alors, que s\'est-il passé ?'],
        ['Lou', 'Era tarde e estava a chover. Eu estava a voltar para o hotel…', 'Il était tard et il pleuvait. Je rentrais à l\'hôtel…'],
        ['Max', 'E depois?', 'Et ensuite ?'],
        ['Lou', 'De repente, um homem correu na minha direção. Tinha uma coisa na mão.', 'Soudain, un homme a couru vers moi. Il avait quelque chose dans la main.'],
        ['Max', 'Que medo! O que fizeste?', 'J\'aurais eu peur ! Qu\'as-tu fait ?'],
        ['Lou', 'Nada! Ele só me devolveu as chaves. Tinham caído no restaurante!', 'Rien ! Il m\'a juste rendu mes clés. Elles étaient tombées au restaurant !'],
      ], [
        ['Quel temps faisait-il ?', ['Il pleuvait', 'Il neigeait', 'Il faisait beau', 'Il y avait du vent']],
        ['Que tenait l\'homme ?', ['Les clés de Lou', 'Un couteau', 'Un téléphone', 'Un parapluie']],
      ]),
      F('Eu ___ a ver televisão quando ligaste.', ['estava', 'estive', 'estou', 'era'], 'Je regardais la télé quand tu as appelé.'),
      F('Enquanto jantávamos, o alarme ___.', ['tocou', 'tocava', 'toca', 'tinha tocar'], 'Pendant qu\'on dînait, l\'alarme a sonné.'),
      C('« Que faisais-tu à minuit ? » :', ['O que estavas a fazer à meia-noite?', 'O que fizeste a fazer à meia-noite?', 'O que estiveste a fazer à meia-noite?', 'O que fazes à meia-noite ontem?']),
      O('Il pleuvait quand nous sommes arrivés.', 'Estava a chover quando chegámos', ['chegávamos']),
      W('Que s\'est-il passé ?', 'O que aconteceu|Que aconteceu|O que é que aconteceu|O que se passou'),
      L('Quando saí de casa, estava muito frio.', 'Quand je suis sorti de chez moi, il faisait très froid.'),
      T('Pendant que je dormais, il a neigé.', ['Enquanto eu dormia, nevou.', 'Enquanto dormi, nevava.', 'Enquanto eu dormi, nevou.', 'Durante eu dormia, nevou.']),
    ]),

  lesson('Há quanto tempo?', 'Depuis combien de temps ?',
    G('Exprimer la durée : há / desde / já / ainda',
      `<b>há</b> + durée + présent = depuis : Moro aqui <b>há</b> três anos. (J\'habite ici depuis trois ans.)<br><b>Há quanto tempo</b> estudas português? (Depuis combien de temps… ?)<br><b>desde</b> + point de départ : Trabalho aqui <b>desde</b> 2020.<br><b>há</b> + durée + passé = il y a : Cheguei <b>há</b> duas horas.<br><b>já</b> = déjà · <b>ainda não</b> = pas encore · <b>nunca</b> = jamais : <b>Já</b> estiveste no Brasil? — <b>Nunca</b> estive.`,
      [['Há quanto tempo vives em Portugal?', 'Depuis combien de temps vis-tu au Portugal ?'], ['Conheço-a desde a escola.', 'Je la connais depuis l\'école.'], ['Ainda não visitei o Porto.', 'Je n\'ai pas encore visité Porto.']],
      'Bonne nouvelle : contrairement à l\'anglais, le portugais utilise le présent comme le français pour « depuis » !'),
    [
      I('há (+ durée)', 'depuis / il y a', 'Estou à espera há meia hora.', 'J\'attends depuis une demi-heure.'),
      I('desde', 'depuis (date)', 'Está doente desde sexta-feira.', 'Il est malade depuis vendredi.'),
      I('já / ainda não', 'déjà / pas encore', 'Já almoçaste? — Ainda não.', 'Tu as déjà déjeuné ? — Pas encore.'),
      I('mudar-se', 'déménager', 'Mudámo-nos para cá em 2020.', 'Nous avons emménagé ici en 2020.'),
      D('Uma nova vizinha', [
        ['Vizinho', 'Há quanto tempo vive em Setúbal?', 'Depuis combien de temps vivez-vous à Setúbal ?'],
        ['Élise', 'Há uns seis anos. Mudámo-nos de Lyon em 2020.', 'Depuis environ six ans. Nous sommes venus de Lyon en 2020.'],
        ['Vizinho', 'E já fala português muito bem!', 'Et vous parlez déjà très bien portugais !'],
        ['Élise', 'Obrigada! Estudo desde que cheguei. Mas ainda não percebo o sotaque do Norte!', 'Merci ! J\'étudie depuis mon arrivée. Mais je ne comprends pas encore l\'accent du Nord !'],
      ], [
        ['Depuis quand Élise vit-elle à Setúbal ?', ['Environ 6 ans', '20 ans', '2 ans', 'Depuis toujours']],
        ['Qu\'est-ce qu\'elle ne comprend pas encore ?', ['L\'accent du Nord', 'Le fado', 'Les horaires', 'Ses voisins']],
      ]),
      F('Moro em Lisboa ___ cinco anos.', ['há', 'desde', 'faz-se', 'durante há'], 'J\'habite à Lisbonne depuis cinq ans.'),
      F('Trabalho aqui ___ 2019.', ['desde', 'há', 'por', 'durante'], 'Je travaille ici depuis 2019.'),
      C('« Tu es déjà allé au Brésil ? — Jamais. »', ['Já estiveste no Brasil? — Nunca.', 'Ainda estiveste no Brasil? — Nunca.', 'Já estás no Brasil? — Não nunca.', 'Jamais estiveste no Brasil?']),
      O('Depuis combien de temps apprends-tu le portugais ?', 'Há quanto tempo aprendes português', ['desde']),
      W('Je n\'ai pas encore mangé.', 'Ainda não comi|Eu ainda não comi|Ainda não almocei|Ainda não jantei'),
      L('Estou à espera há vinte minutos.', 'J\'attends depuis vingt minutes.'),
      T('Je la connais depuis l\'enfance.', ['Conheço-a desde a infância.', 'Conheço-a há a infância.', 'A conheço desde infância.', 'Conheci-a desde a infância.']),
    ]),
]),

unit('pt_b1_3', 'B1', 'Casa e serviços', 'Logement et services', '🔑', '#84cc16', [
  lesson('Arrendar casa', 'Louer un appartement',
    G('Les pronoms compléments : o, a, lhe… et leur place',
      `COD : <b>o</b> (le), <b>a</b> (la), <b>os</b>, <b>as</b>. COI : <b>lhe</b> (lui), <b>lhes</b> (leur). Aussi <b>me, te, nos</b>.<br><b>Position normale (Portugal) : APRÈS le verbe</b> : Vejo-<b>o</b> amanhã. Ligo-<b>lhe</b> logo.<br><b>AVANT le verbe</b> après : não, nunca, já, também, quem, que, onde… : <b>Não o</b> vejo. <b>Já a</b> vi.<br>Après -r, -s, -z, le pronom devient <b>-lo / -la</b> : Vou comprá-<b>lo</b> (comprar + o). Fi-<b>lo</b> (fiz + o).`,
      [['Vou visitá-lo amanhã.', 'Je vais le visiter demain.'], ['Não o conheço.', 'Je ne le connais pas.'], ['O senhorio ligou-lhe?', 'Le propriétaire vous a appelé ?']],
      'C\'est LA grande différence avec le Brésil (« Eu te vejo »). Au Portugal, commencer une phrase par un pronom sonne faux.'),
    [
      I('a renda', 'le loyer', 'A renda é de 900 euros.', 'Le loyer est de 900 euros.'),
      I('o senhorio', 'le propriétaire (bailleur)', 'O senhorio mora no rés-do-chão.', 'Le propriétaire habite au rez-de-chaussée.'),
      I('um T2', 'un appartement 2 chambres', 'Procuro um T2 perto do centro.', 'Je cherche un deux-chambres près du centre.'),
      I('mobilado / despesas incluídas', 'meublé / charges comprises', 'É mobilado e com despesas incluídas.', 'C\'est meublé, charges comprises.'),
      D('Visitar um apartamento', [
        ['Agente', 'Esta é a sala. Tem muita luz, como vê.', 'Voici le salon. Très lumineux, comme vous voyez.'],
        ['Inquilina', 'É lindíssima. Quanto é a renda?', 'Il est superbe. Quel est le loyer ?'],
        ['Agente', 'Novecentos euros por mês, sem despesas.', 'Neuf cents euros par mois, hors charges.'],
        ['Inquilina', 'E a caução?', 'Et la caution ?'],
        ['Agente', 'Dois meses. Se quiser, falo com o senhorio hoje e ligo-lhe amanhã.', 'Deux mois. Si vous voulez, je parle au propriétaire aujourd\'hui et je vous rappelle demain.'],
      ], [
        ['Les charges sont-elles comprises ?', ['Non', 'Oui', 'En partie', 'On ne sait pas']],
        ['Combien de mois de caution ?', ['Deux', 'Un', 'Trois', 'Aucun']],
      ]),
      F('Conheces o Pedro? — Sim, conheço-___.', ['o', 'lo', 'lhe', 'a'], 'Tu connais Pedro ? — Oui, je le connais.'),
      F('Não ___ vi ontem.', ['a', '-a', 'lhe', 'la'], 'Je ne l\'ai pas vue hier.', 'Après « não », le pronom passe devant.'),
      C('« Je vais l\'acheter » (le livre) :', ['Vou comprá-lo.', 'Vou comprar-o.', 'Vou o comprar-lo.', 'Vou comprar-lhe.']),
      O('Je vous appelle demain.', 'Ligo-lhe amanhã', ['lhe ligo']),
      W('Le loyer est de 800 euros.', 'A renda é de 800 euros|A renda é de oitocentos euros|A renda é 800 euros|A renda é oitocentos euros'),
      L('Já a conheço, é a minha vizinha.', 'Je la connais déjà, c\'est ma voisine.'),
      T('Je ne le connais pas.', ['Não o conheço.', 'Não conheço-o.', 'Eu o não conheço.', 'Não lhe conheço-o.']),
    ]),

  lesson('Reclamações', 'Problèmes et réclamations',
    G('« acabar de », « voltar a » et se plaindre',
      `<b>acabar de</b> + infinitif = venir de : <b>Acabei de</b> comprar esta máquina. (Je viens d\'acheter…)<br><b>voltar a</b> + infinitif = re-faire : A luz <b>voltou a</b> falhar. (La lumière a encore sauté.)<br>Problèmes : <b>está avariado/a</b> (en panne) · <b>não funciona</b> · <b>está estragado</b> (abîmé, pourri).<br>Réclamer : <b>Queria fazer uma reclamação</b> · <b>Queria o reembolso</b> · <b>Queria trocar</b> (échanger).`,
      [['O elevador está avariado outra vez.', 'L\'ascenseur est encore en panne.'], ['Acabei de chegar.', 'Je viens d\'arriver.'], ['Posso ver o livro de reclamações?', 'Puis-je voir le livre de réclamations ?']],
      'Au Portugal, tout commerce doit avoir un « livro de reclamações » (livre de réclamations officiel). Le demander suffit souvent à débloquer une situation !'),
    [
      I('avariado/a', 'en panne', 'O carro está avariado.', 'La voiture est en panne.'),
      I('acabar de', 'venir de', 'Acabámos de jantar.', 'Nous venons de dîner.'),
      I('o reembolso', 'le remboursement', 'Queria o reembolso, se faz favor.', 'Je voudrais être remboursé.'),
      I('trocar', 'échanger', 'Posso trocar este casaco?', 'Je peux échanger cette veste ?'),
      D('Numa loja de eletrodomésticos', [
        ['Funcionário', 'Bom dia, em que posso ajudar?', 'Bonjour, je peux vous aider ?'],
        ['Cliente', 'Comprei esta máquina de café a semana passada e já está avariada.', 'J\'ai acheté cette machine à café la semaine dernière et elle est déjà en panne.'],
        ['Funcionário', 'Lamento. Já experimentou desligá-la e voltar a ligá-la?', 'Je suis désolé. Vous avez essayé de l\'éteindre et la rallumer ?'],
        ['Cliente', 'Já, várias vezes. Queria o reembolso.', 'Oui, plusieurs fois. Je voudrais être remboursé.'],
        ['Funcionário', 'Com certeza. Tem a fatura?', 'Bien sûr. Vous avez la facture ?'],
      ], [
        ['Quel appareil est en panne ?', ['Une machine à café', 'Un lave-linge', 'Un téléphone', 'Une télé']],
        ['Que demande le vendeur à la fin ?', ['La facture', 'Le numéro de téléphone', 'La carte bancaire', 'Le carton']],
      ]),
      F('Acabei ___ chegar a casa.', ['de', 'a', 'que', 'por'], 'Je viens de rentrer à la maison.'),
      F('O frigorífico está ___.', ['avariado', 'em pane', 'quebrado-se', 'parado de'], 'Le frigo est en panne.'),
      C('« Ça a encore planté » :', ['Voltou a falhar.', 'Acabou de falhar outra vez.', 'Re-falhou.', 'Falhou de novo-se.']),
      O('Je voudrais faire une réclamation.', 'Queria fazer uma reclamação', ['quero-me']),
      W('Je voudrais être remboursé(e).', 'Queria o reembolso|Queria ser reembolsado|Queria ser reembolsada|Queria um reembolso'),
      L('Lamento, mas o elevador está avariado.', 'Je suis désolé, mais l\'ascenseur est en panne.'),
      T('Je peux échanger ce pull ?', ['Posso trocar esta camisola?', 'Posso mudar este pulôver?', 'Posso trocar esta suéter?', 'Pode-se trocar-me esta camisola?'], '« camisola » = pull au Portugal.'),
    ]),

  lesson('Ao telefone', 'Au téléphone',
    G('Téléphoner + le futur simple',
      `Au téléphone au Portugal : on décroche avec <b>Estou?</b> ou <b>Sim?</b> ; l\'appelant peut dire <b>Está lá?</b> / <b>Está?</b><br><b>Quem fala?</b> = C\'est de la part de qui ? · <b>Um momento, vou passar.</b> = Je vous le passe.<br><b>Futuro simples</b> (écrit, formel, promesses) : infinitif + <b>-ei, -ás, -á, -emos, -ão</b> : ligar<b>ei</b>, falar<b>á</b>.<br>Irréguliers : dizer → <b>direi</b>, fazer → <b>farei</b>, trazer → <b>trarei</b>.`,
      [['Estou? Quem fala?', 'Allô ? Qui est à l\'appareil ?'], ['Ligarei amanhã sem falta.', 'J\'appellerai demain sans faute.'], ['Pode dizer-lhe que liguei?', 'Pouvez-vous lui dire que j\'ai appelé ?']],
      'À l\'oral on préfère « vou ligar ». Curiosité du Portugal formel : la mésoclise, pronom AU MILIEU du futur : « Dir-lhe-ei » (je lui dirai). À reconnaître seulement !'),
    [
      I('Estou? / Está?', 'Allô ?', 'Estou? Sim, é a Ana.', 'Allô ? Oui, c\'est Ana.'),
      I('Quem fala?', 'Qui est à l\'appareil ?', 'Boa tarde, quem fala?', 'Bonjour, qui est à l\'appareil ?'),
      I('deixar recado', 'laisser un message', 'Quer deixar recado?', 'Voulez-vous laisser un message ?'),
      I('voltar a ligar', 'rappeler', 'Volto a ligar mais tarde.', 'Je rappelle plus tard.'),
      D('Ligar para o dentista', [
        ['Rececionista', 'Clínica Dentária Sorriso, bom dia.', 'Clinique dentaire Sorriso, bonjour.'],
        ['Camille', 'Bom dia, fala Camille Roux. Podia falar com a doutora Silva?', 'Bonjour, c\'est Camille Roux. Pourrais-je parler au Dr Silva ?'],
        ['Rececionista', 'Lamento, está com um paciente. Quer deixar recado?', 'Désolée, elle est avec un patient. Voulez-vous laisser un message ?'],
        ['Camille', 'Sim, preciso de mudar a consulta de quinta-feira.', 'Oui, je dois changer mon rendez-vous de jeudi.'],
        ['Rececionista', 'Muito bem. Ela ligar-lhe-á esta tarde.', 'Très bien. Elle vous rappellera cet après-midi.'],
      ], [
        ['Pourquoi Camille appelle-t-elle ?', ['Changer un rendez-vous', 'Prendre un premier rendez-vous', 'Payer', 'Se plaindre']],
        ['« ligar-lhe-á » signifie :', ['elle vous appellera', 'appelez-la', 'elle vous a appelé', 'il faut l\'appeler']],
      ]),
      F('Amanhã ___ sem falta. (ligar)', ['ligarei', 'ligo-ei', 'ligava', 'liguei'], 'Demain j\'appellerai sans faute.'),
      F('___ fala? — É o Pedro.', ['Quem', 'Que', 'Qual', 'Quando'], 'Qui est à l\'appareil ? — C\'est Pedro.'),
      C('Au Portugal, en décrochant le téléphone on dit souvent :', ['Estou?', 'Alô?', 'Pronto?', 'Diga-me lá quem é?']),
      O('Pouvez-vous lui dire que j\'ai appelé ?', 'Pode dizer-lhe que liguei', ['lhe dizer']),
      W('Je rappelle plus tard.', 'Volto a ligar mais tarde|Ligo mais tarde|Ligo outra vez mais tarde|Torno a ligar mais tarde'),
      L('Um momento, vou passar a chamada.', 'Un instant, je vous passe l\'appel.'),
      T('Voulez-vous laisser un message ?', ['Quer deixar recado?', 'Quer deixar uma mensagem de voz-se?', 'Queres deixa recado?', 'Quer recado deixar?']),
    ]),
]),

// ─────────────── B2 ───────────────
unit('pt_b2_1', 'B2', 'Opiniões', 'Donner son avis, débattre', '💬', '#f43f5e', [
  lesson('Dar a opinião', 'Donner son opinion',
    G('Opinion : « acho que » + indicatif / « não acho que » + subjonctif',
      `Affirmer : <b>Acho que</b> / <b>Penso que</b> / <b>Na minha opinião</b> / <b>Para mim</b> + <b>indicatif</b> : Acho que <b>é</b> caro.<br>Nier ou douter : <b>Não acho que</b> / <b>Duvido que</b> + <b>subjonctif</b> : Não acho que <b>seja</b> caro.<br>Accord : <b>Concordo</b> (plenamente). · <b>Tens razão.</b> · <b>Pois é.</b><br>Désaccord : <b>Não concordo.</b> · <b>Percebo, mas…</b> · <b>Não é bem assim.</b>`,
      [['Acho que o turismo é bom para a cidade.', 'Je pense que le tourisme est bon pour la ville.'], ['Não acho que seja uma boa ideia.', 'Je ne pense pas que ce soit une bonne idée.'], ['Percebo o que queres dizer, mas…', 'Je comprends ce que tu veux dire, mais…']],
      'Même logique qu\'en français : « je pense que c\'EST » / « je ne pense pas que ce SOIT ».'),
    [
      I('Acho que…', 'Je pense que…', 'Acho que vai chover.', 'Je pense qu\'il va pleuvoir.'),
      I('Concordo / Não concordo', 'Je suis d\'accord / pas d\'accord', 'Concordo contigo.', 'Je suis d\'accord avec toi.'),
      I('Tens razão', 'Tu as raison', 'Tens toda a razão!', 'Tu as entièrement raison !'),
      I('por outro lado', 'd\'un autre côté', 'Por outro lado, é muito prático.', 'D\'un autre côté, c\'est très pratique.'),
      D('Debate: carros no centro histórico?', [
        ['Moderadora', 'Devemos proibir os carros no centro histórico?', 'Faut-il interdire les voitures dans le centre historique ?'],
        ['Sara', 'Sem dúvida. Na minha opinião, o ar ficaria mais limpo e as ruas mais seguras.', 'Sans aucun doute. À mon avis, l\'air serait plus propre et les rues plus sûres.'],
        ['Miguel', 'Percebo, mas não acho que seja justo para os comerciantes. Precisam de entregas.', 'Je comprends, mais je ne pense pas que ce soit juste pour les commerçants. Ils ont besoin de livraisons.'],
        ['Sara', 'Tem razão. As entregas podiam ser feitas de manhã cedo.', 'Vous avez raison. Les livraisons pourraient se faire tôt le matin.'],
        ['Miguel', 'Pois, isso talvez funcione.', 'Oui, ça pourrait marcher.'],
      ], [
        ['Quelle est la position de Sara ?', ['Pour l\'interdiction', 'Contre', 'Sans avis', 'Pour plus de parkings']],
        ['Pourquoi « seja » après « não acho que » ?', ['Négation d\'opinion → subjonctif', 'C\'est le passé', 'C\'est une erreur', 'C\'est le futur']],
      ]),
      F('Não acho que ___ boa ideia.', ['seja', 'é', 'será', 'era'], 'Je ne pense pas que ce soit une bonne idée.'),
      F('Acho que ___ razão.', ['tens', 'tenhas', 'tenha', 'tiver'], 'Je pense que tu as raison.', '« Acho que » affirmatif → indicatif.'),
      C('Pour contester poliment :', ['Percebo, mas…', 'Estás enganadíssimo.', 'Que disparate!', 'Não.']),
      O('Je ne suis pas d\'accord avec toi.', 'Não concordo contigo', ['com tu']),
      W('Tu as raison.', 'Tens razão|Tens toda a razão'),
      L('Por outro lado, os transportes públicos são mais baratos.', 'D\'un autre côté, les transports en commun sont moins chers.'),
      T('Je doute qu\'il vienne.', ['Duvido que ele venha.', 'Duvido que ele vem.', 'Duvido que ele virá.', 'Duvido que ele vir.']),
    ]),

  lesson('O conjuntivo presente', 'Le subjonctif présent',
    G('Le subjonctif présent (presente do conjuntivo)',
      `Formation : partir du « eu » du présent, enlever le -o, ajouter les terminaisons « inversées » :<br><b>-AR → -e</b> : falar → (falo) → fal<b>e</b>, fal<b>es</b>, fal<b>e</b>, fal<b>emos</b>, fal<b>em</b><br><b>-ER/-IR → -a</b> : fazer → (faço) → faç<b>a</b>, faç<b>as</b>… · ter → tenh<b>a</b><br>Irréguliers : ser → <b>seja</b> · estar → <b>esteja</b> · ir → <b>vá</b> · haver → <b>haja</b> · saber → <b>saiba</b> · querer → <b>queira</b> · dar → <b>dê</b><br>Après : <b>espero que</b>, <b>quero que</b>, <b>é preciso que</b>, <b>é importante que</b>, <b>talvez</b>, <b>embora</b> (bien que), <b>para que</b>.`,
      [['Espero que gostes do presente.', 'J\'espère que le cadeau te plaira.'], ['É preciso que chegues a horas.', 'Il faut que tu arrives à l\'heure.'], ['Talvez ele venha amanhã.', 'Peut-être qu\'il viendra demain.']],
      'Formules du quotidien : « Que tenhas um bom dia! », « Bom fim de semana, que corra tudo bem! », « Oxalá! » (pourvu que !).'),
    [
      I('Espero que…', 'J\'espère que…', 'Espero que esteja bom tempo.', 'J\'espère qu\'il fera beau.'),
      I('talvez', 'peut-être', 'Talvez vá ao Porto.', 'J\'irai peut-être à Porto.'),
      I('embora', 'bien que', 'Embora esteja cansado, vou sair.', 'Bien que je sois fatigué, je vais sortir.'),
      I('Oxalá!', 'Pourvu que !', 'Oxalá não chova amanhã!', 'Pourvu qu\'il ne pleuve pas demain !'),
      D('Antes do casamento (avant le mariage)', [
        ['Mãe', 'Espero que esteja tudo pronto para sábado.', 'J\'espère que tout sera prêt pour samedi.'],
        ['Filha', 'Está quase. Só é preciso que o fotógrafo confirme a hora.', 'Presque. Il faut juste que le photographe confirme l\'heure.'],
        ['Mãe', 'E o tempo? Oxalá não chova!', 'Et la météo ? Pourvu qu\'il ne pleuve pas !'],
        ['Filha', 'Talvez chova de manhã, mas embora esteja nublado, a festa é no jardim!', 'Il pleuvra peut-être le matin, mais même s\'il fait gris, la fête est dans le jardin !'],
      ], [
        ['Qui doit confirmer l\'heure ?', ['Le photographe', 'Le traiteur', 'Le prêtre', 'La mère']],
        ['Où a lieu la fête ?', ['Dans le jardin', 'À l\'église', 'Au restaurant', 'À la plage']],
      ]),
      F('Espero que ___ boas férias.', ['tenhas', 'tens', 'terás', 'tiveres'], 'J\'espère que tu passeras de bonnes vacances.'),
      F('É preciso que nós ___ cedo.', ['saiamos', 'saímos', 'sairmos', 'saíamos'], 'Il faut que nous partions tôt.'),
      C('Subjonctif présent de « ser » (eu) :', ['seja', 'sou', 'fosse', 'for']),
      O('J\'espère que tu vas bien.', 'Espero que estejas bem', ['estás']),
      W('Pourvu qu\'il ne pleuve pas !', 'Oxalá não chova|Tomara que não chova|Espero que não chova'),
      L('Talvez eles venham jantar connosco.', 'Peut-être qu\'ils viendront dîner avec nous.'),
      T('Bien qu\'il fasse froid, je vais nager.', ['Embora esteja frio, vou nadar.', 'Embora está frio, vou nadar.', 'Embora faça frio de, vou nadar.', 'Mesmo que está frio, vou nadar.']),
    ]),

  lesson('Se eu fosse…', 'Si j\'étais…',
    G('L\'hypothèse : imparfait du subjonctif + conditionnel',
      `Hypothèse irréelle : <b>Se</b> + <b>imperfeito do conjuntivo</b>, + <b>condicional</b> (ou imparfait à l\'oral).<br>Formation : 3e pers. pluriel du passé simple – <b>ram</b> + <b>-sse</b> : falaram → fala<b>sse</b> · tiveram → tive<b>sse</b> · foram → fo<b>sse</b> · fizeram → fize<b>sse</b> · puderam → pude<b>sse</b>.<br>Conditionnel : infinitif + <b>-ia</b> : compraria, viveria (irréguliers : faria, diria, traria).<br>→ <b>Se eu ganhasse</b> a lotaria, <b>comprava / compraria</b> uma casa.`,
      [['Se eu fosse rico, viajava pelo mundo.', 'Si j\'étais riche, je voyagerais autour du monde.'], ['O que farias se perdesses o emprego?', 'Que ferais-tu si tu perdais ton travail ?'], ['Se eu fosse a ti, aceitava.', 'Si j\'étais toi, j\'accepterais.']],
      'À l\'oral au Portugal, on remplace très souvent le conditionnel par l\'imparfait : « Se pudesse, ia » plutôt que « iria ».'),
    [
      I('Se eu fosse a ti', 'À ta place', 'Se eu fosse a ti, ligava-lhe.', 'À ta place, je l\'appellerais.'),
      I('Gostava de…', 'J\'aimerais…', 'Gostava de viver no estrangeiro.', 'J\'aimerais vivre à l\'étranger.'),
      I('ganhar a lotaria', 'gagner au loto', 'Se ganhasse a lotaria, deixava de trabalhar.', 'Si je gagnais au loto, j\'arrêterais de travailler.'),
      I('se pudesse', 'si je pouvais', 'Se pudesse, ficava mais uma semana.', 'Si je pouvais, je resterais une semaine de plus.'),
      D('A vida de sonho', [
        ['Tomás', 'O que farias se não precisasses de trabalhar?', 'Que ferais-tu si tu n\'avais pas besoin de travailler ?'],
        ['Jade', 'Dava a volta ao mundo de veleiro. E tu?', 'Je ferais le tour du monde en voilier. Et toi ?'],
        ['Tomás', 'Se tivesse dinheiro, abria uma pequena pousada no Alentejo.', 'Si j\'avais de l\'argent, j\'ouvrirais une petite auberge dans l\'Alentejo.'],
        ['Jade', 'Se eu fosse a ti, começava a poupar já!', 'À ta place, je commencerais à économiser tout de suite !'],
      ], [
        ['Quel est le rêve de Tomás ?', ['Ouvrir une auberge dans l\'Alentejo', 'Faire le tour du monde', 'Arrêter de travailler', 'Gagner au loto']],
        ['« Se eu fosse a ti » signifie :', ['À ta place', 'Si j\'allais chez toi', 'Si j\'étais avec toi', 'Si tu étais moi']],
      ]),
      F('Se eu ___ rico, comprava um barco.', ['fosse', 'for', 'seja', 'era'], 'Si j\'étais riche, j\'achèterais un bateau.'),
      F('Se ___ tempo, aprendia a tocar guitarra.', ['tivesse', 'tiver', 'tenha', 'tinha'], 'Si j\'avais le temps, j\'apprendrais la guitare.'),
      C('Quelle phrase est correcte ?', ['Se eu pudesse, ia contigo.', 'Se eu posso, ia contigo.', 'Se eu puder, ia contigo ontem.', 'Se eu podia, iria-se contigo.']),
      O('À ta place, je n\'accepterais pas.', 'Se eu fosse a ti não aceitava', ['for']),
      W('J\'aimerais vivre au Portugal.', 'Gostava de viver em Portugal|Gostaria de viver em Portugal'),
      L('Se vivêssemos perto do mar, íamos nadar todos os dias.', 'Si nous habitions près de la mer, nous irions nager tous les jours.'),
      T('Que ferais-tu si tu gagnais au loto ?', ['O que farias se ganhasses a lotaria?', 'O que fazes se ganhares a lotaria?', 'O que farias se ganhas a lotaria?', 'O que fazerias se ganhasses a lotaria?']),
    ]),
]),

unit('pt_b2_2', 'B2', 'Contar histórias', 'Raconter une histoire', '📖', '#d946ef', [
  lesson('O que já tinha acontecido', 'Ce qui s\'était passé avant',
    G('Le plus-que-parfait (mais-que-perfeito composto)',
      `<b>tinha</b> (imparfait de ter) + <b>participe passé</b> = action antérieure à une autre action passée.<br>Quando cheguei, o comboio <b>já tinha partido</b>.<br>Participes irréguliers : fazer → <b>feito</b> · dizer → <b>dito</b> · ver → <b>visto</b> · pôr → <b>posto</b> · escrever → <b>escrito</b> · abrir → <b>aberto</b> · vir → <b>vindo</b>.`,
      [['Nunca tinha visto o mar antes daquela viagem.', 'Je n\'avais jamais vu la mer avant ce voyage.'], ['Quando a polícia chegou, o ladrão já tinha fugido.', 'Quand la police est arrivée, le voleur s\'était déjà enfui.'], ['Ela estava cansada porque não tinha dormido.', 'Elle était fatiguée car elle n\'avait pas dormi.']],
      'Attention : le « passé composé » portugais (tenho feito) ne correspond PAS au passé composé français — il signifie « ces derniers temps, de façon répétée ». « Tenho trabalhado muito » = je travaille beaucoup ces temps-ci.'),
    [
      I('já tinha…', 'avait déjà…', 'O filme já tinha começado.', 'Le film avait déjà commencé.'),
      I('aperceber-se', 'se rendre compte', 'Apercebi-me de que tinha perdido a carteira.', 'Je me suis rendu compte que j\'avais perdu mon portefeuille.'),
      I('nunca tinha…', 'n\'avait jamais…', 'Nunca tinha andado de avião.', 'Je n\'avais jamais pris l\'avion.'),
      I('esquecer-se de', 'oublier', 'Esqueci-me do passaporte.', 'J\'ai oublié mon passeport.'),
      D('Um mau começo de férias', [
        ['Nina', 'Como correu o início das férias?', 'Comment s\'est passé le début des vacances ?'],
        ['Yann', 'Um desastre! No aeroporto, apercebi-me de que tinha deixado o passaporte em casa.', 'Une catastrophe ! À l\'aéroport, je me suis rendu compte que j\'avais laissé mon passeport à la maison.'],
        ['Nina', 'Que horror! E o que fizeste?', 'L\'horreur ! Et qu\'as-tu fait ?'],
        ['Yann', 'A minha vizinha trouxe-mo, mas quando chegou, o avião já tinha partido.', 'Ma voisine me l\'a apporté, mais quand elle est arrivée, l\'avion était déjà parti.'],
      ], [
        ['Qu\'avait oublié Yann ?', ['Son passeport', 'Ses billets', 'Sa valise', 'Son téléphone']],
        ['« trouxe-mo » = trouxe + me + o =', ['elle me l\'a apporté', 'elle m\'a apporté', 'elle l\'a apporté', 'je l\'ai apporté']],
      ]),
      F('Quando cheguei, eles já ___ jantado.', ['tinham', 'têm', 'tiveram', 'tinha'], 'Quand je suis arrivé, ils avaient déjà dîné.'),
      F('Eu nunca tinha ___ aquele filme.', ['visto', 'vido', 'vi', 'ver'], 'Je n\'avais jamais vu ce film.'),
      C('« Tenho trabalhado muito » signifie :', ['Je travaille beaucoup ces temps-ci', 'J\'ai beaucoup travaillé (hier)', 'J\'avais beaucoup travaillé', 'Je travaillerai beaucoup']),
      O('Le train était déjà parti.', 'O comboio já tinha partido', ['tem']),
      W('J\'ai oublié mon passeport.', 'Esqueci-me do passaporte|Esqueci o passaporte|Esqueci-me do meu passaporte|Esqueci o meu passaporte'),
      L('Quando chegámos, o restaurante já tinha fechado.', 'Quand nous sommes arrivés, le restaurant avait déjà fermé.'),
      T('Elle avait déjà tout fait.', ['Ela já tinha feito tudo.', 'Ela já tinha fazido tudo.', 'Ela já tem feito tudo.', 'Ela já fazia tudo feito.']),
    ]),

  lesson('Discurso indireto', 'Rapporter des paroles',
    G('Le discours indirect',
      `Comme en français, on « recule » les temps :<br>« Estou cansado » → Ele disse que <b>estava</b> cansado.<br>« Vou ligar » → Ela disse que <b>ia</b> ligar.<br>« Comprei » → Ele disse que <b>tinha comprado</b>.<br>« Ligarei » → Disse que <b>ligaria</b>.<br>Questions : Perguntou <b>se</b> eu queria vir. / Perguntou <b>onde</b> eu morava.<br>Ordres : « Liga-me! » → Pediu-me <b>que lhe ligasse</b> / <b>para lhe ligar</b>.`,
      [['Disse-me que se ia mudar para Lisboa.', 'Elle m\'a dit qu\'elle allait déménager à Lisbonne.'], ['Ele perguntou se tínhamos reserva.', 'Il a demandé si nous avions une réservation.'], ['Pediu-me para esperar.', 'Il m\'a demandé d\'attendre.']],
      '« pedir » = demander quelque chose (une faveur) ; « perguntar » = poser une question. Ne pas confondre !'),
    [
      I('dizer que', 'dire que', 'Ela disse que estava atrasada.', 'Elle a dit qu\'elle était en retard.'),
      I('perguntar se', 'demander si', 'Perguntou se eu precisava de ajuda.', 'Il a demandé si j\'avais besoin d\'aide.'),
      I('pedir para', 'demander de', 'Pediu-me para fechar a porta.', 'Il m\'a demandé de fermer la porte.'),
      I('prometer', 'promettre', 'Prometeu que vinha.', 'Il a promis qu\'il viendrait.'),
      D('Novidades no escritório', [
        ['Rita', 'Falaste com o Bruno ontem?', 'Tu as parlé à Bruno hier ?'],
        ['Zoe', 'Falei! Disse-me que ia sair da empresa.', 'Oui ! Il m\'a dit qu\'il allait quitter l\'entreprise.'],
        ['Rita', 'A sério? Disse porquê?', 'Sérieux ? Il a dit pourquoi ?'],
        ['Zoe', 'Disse que tinha arranjado trabalho no Canadá e que se mudava em março.', 'Il a dit qu\'il avait trouvé du travail au Canada et qu\'il déménageait en mars.'],
        ['Rita', 'Ah! Na semana passada perguntou-me se eu conhecia alguém em Montreal… agora percebo!', 'Ah ! La semaine dernière il m\'a demandé si je connaissais quelqu\'un à Montréal… maintenant je comprends !'],
      ], [
        ['Où Bruno va-t-il travailler ?', ['Au Canada', 'Aux États-Unis', 'En France', 'Au Brésil']],
        ['Quand déménage-t-il ?', ['En mars', 'En mai', 'La semaine prochaine', 'Il ne sait pas']],
      ]),
      F('Ela disse que ___ cansada.', ['estava', 'está', 'esteve', 'estará'], 'Elle a dit qu\'elle était fatiguée.'),
      F('Ele ___-me se eu queria café.', ['perguntou', 'pediu', 'disse', 'contou'], 'Il m\'a demandé si je voulais du café.'),
      C('« Vou ligar-te », disse ele → Ele disse que…', ['me ia ligar', 'vou ligar-te', 'me liga', 'ligou-me']),
      O('Il a demandé si nous étions français.', 'Perguntou se éramos franceses', ['somos']),
      W('Il a dit qu\'il était fatigué.', 'Disse que estava cansado|Ele disse que estava cansado'),
      L('Prometeu que vinha jantar connosco.', 'Il a promis qu\'il viendrait dîner avec nous.'),
      T('Elle m\'a demandé de l\'attendre.', ['Pediu-me para esperar por ela.', 'Perguntou-me para esperar por ela.', 'Pediu-me se esperava ela.', 'Disse-me esperar-la.']),
    ]),

  lesson('Quando chegares…', 'Le futur du subjonctif',
    G('Le futur du subjonctif (futuro do conjuntivo) — une spécialité !',
      `Ce temps n\'existe plus en français, mais il est <b>très courant</b> en portugais après <b>quando</b>, <b>se</b>, <b>logo que</b>, <b>assim que</b>, <b>quem</b>, <b>onde</b>, <b>como</b> pour un futur.<br>Formation : 3e pers. pluriel du passé simple – <b>-ram</b> + <b>-r, -res, -r, -rmos, -rem</b> :<br>falaram → fala<b>r</b>, fala<b>res</b> · tiveram → tive<b>r</b> · foram → fo<b>r</b> · puderam → pude<b>r</b> · fizeram → fize<b>r</b> · quiseram → quise<b>r</b> · vieram → vie<b>r</b>`,
      [['Quando chegares, liga-me.', 'Quand tu arriveras, appelle-moi.'], ['Se puderes, vem jantar.', 'Si tu peux, viens dîner.'], ['Quem quiser, pode vir.', 'Ceux qui veulent peuvent venir.']],
      'Le français dit « quand tu arriveras » (futur) ou « si tu peux » (présent) ; le portugais utilise le futur du subjonctif dans les deux cas.'),
    [
      I('quando puderes', 'quand tu pourras', 'Liga-me quando puderes.', 'Appelle-moi quand tu pourras.'),
      I('se quiseres', 'si tu veux', 'Se quiseres, vamos juntos.', 'Si tu veux, on y va ensemble.'),
      I('assim que', 'dès que', 'Assim que souber, digo-te.', 'Dès que je saurai, je te le dis.'),
      I('como quiser', 'comme vous voulez', 'Pode pagar como quiser.', 'Vous pouvez payer comme vous voulez.'),
      D('Instruções antes da viagem', [
        ['Mãe', 'Quando chegares ao aeroporto, manda-me uma mensagem.', 'Quand tu arriveras à l\'aéroport, envoie-moi un message.'],
        ['Hugo', 'Está bem. E se o voo atrasar?', 'D\'accord. Et si le vol a du retard ?'],
        ['Mãe', 'Se atrasar, liga-me. Assim que souberes a hora de chegada, avisa a tua tia.', 'S\'il a du retard, appelle-moi. Dès que tu connaîtras l\'heure d\'arrivée, préviens ta tante.'],
        ['Hugo', 'Combinado. Se tiver tempo, compro-te um presente!', 'Ça marche. Si j\'ai le temps, je t\'achète un cadeau !'],
      ], [
        ['Que doit faire Hugo en arrivant à l\'aéroport ?', ['Envoyer un message', 'Appeler sa tante', 'Acheter un cadeau', 'Prendre un taxi']],
        ['Qui doit-il prévenir de l\'heure d\'arrivée ?', ['Sa tante', 'Sa mère', 'Son père', 'Son ami']],
      ]),
      F('Quando ___ a Lisboa, avisa-me.', ['chegares', 'chegas', 'chegarás', 'chegues'], 'Quand tu arriveras à Lisbonne, préviens-moi.'),
      F('Se ___ tempo, vou ao museu.', ['tiver', 'tenho', 'tivesse', 'ter'], 'Si j\'ai le temps, j\'irai au musée.'),
      C('Futur du subjonctif de « ser / ir » (eu) :', ['for', 'fosse', 'seja', 'serei']),
      O('Appelle-moi quand tu pourras.', 'Liga-me quando puderes', ['podes']),
      W('Si tu veux, on y va ensemble.', 'Se quiseres, vamos juntos|Se quiseres vamos juntos|Se quiseres, vamos juntas|Se quiseres, vamos lá juntos'),
      L('Assim que souber alguma coisa, ligo-te.', 'Dès que je saurai quelque chose, je t\'appelle.'),
      T('Ceux qui veulent peuvent venir.', ['Quem quiser pode vir.', 'Quem quer poder vir.', 'Quem queira pode vir.', 'Quem quiserem podem vir.']),
    ]),
]),

unit('pt_b2_3', 'B2', 'Português autêntico', 'Parler comme un Portugais', '🚀', '#eab308', [
  lesson('Vende-se, fala-se', 'Le « se » impersonnel et le passif',
    G('Le « se » impersonnel et la voix passive',
      `Là où le français dit « on », le portugais utilise souvent <b>se</b> : <b>Fala-se</b> inglês (on parle anglais). <b>Vende-se</b> (à vendre). <b>Aluga-se</b> (à louer). <b>Não se pode</b> fumar.<br>Le verbe s\'accorde avec le sujet : <b>Vendem-se</b> casas. <b>Alugam-se</b> quartos.<br>Passif : <b>ser + participe</b> (accordé) : O castelo <b>foi construído</b> no século XII. A ponte <b>foi inaugurada</b> em 1966.`,
      [['Aqui fala-se francês.', 'Ici, on parle français.'], ['Alugam-se bicicletas.', 'Location de vélos.'], ['O mosteiro foi construído pelos monges.', 'Le monastère a été construit par les moines.']],
      'Sur les panneaux au Portugal : « Vende-se » (à vendre), « Aluga-se » (à louer), « Precisa-se de empregado » (on recherche un employé), « É proibido fumar ».'),
    [
      I('Vende-se / Aluga-se', 'À vendre / À louer', 'Vende-se apartamento T3.', 'Appartement trois chambres à vendre.'),
      I('Precisa-se de…', 'On recherche…', 'Precisa-se de cozinheiro.', 'On recherche un cuisinier.'),
      I('foi construído', 'a été construit', 'Este palácio foi construído em 1840.', 'Ce palais a été construit en 1840.'),
      I('é proibido', 'il est interdit de', 'É proibido estacionar aqui.', 'Il est interdit de stationner ici.'),
      D('Uma visita guiada em Sintra', [
        ['Guia', 'Este palácio foi construído no século dezanove.', 'Ce palais a été construit au XIXe siècle.'],
        ['Turista', 'Ainda é habitado?', 'Il est encore habité ?'],
        ['Guia', 'Já não. Foi comprado pelo Estado e foi restaurado nos anos noventa.', 'Plus maintenant. Il a été acheté par l\'État et restauré dans les années 90.'],
        ['Turista', 'Pode-se tirar fotografias?', 'On peut prendre des photos ?'],
        ['Guia', 'Pode, mas não se pode usar flash lá dentro.', 'Oui, mais on ne peut pas utiliser le flash à l\'intérieur.'],
      ], [
        ['Quand le palais a-t-il été construit ?', ['Au XIXe siècle', 'Au XIIe siècle', 'Dans les années 90', 'Au XVIe siècle']],
        ['Qu\'est-ce qui est interdit ?', ['Le flash', 'Les photos', 'Les enfants', 'Les sacs']],
      ]),
      F('___ quartos. (panneau : chambres à louer)', ['Alugam-se', 'Aluga-se', 'Alugar-se', 'Alugam'], 'Chambres à louer.', 'Sujet pluriel (quartos) → verbe pluriel.'),
      F('A ponte foi ___ em 1966.', ['inaugurada', 'inaugurado', 'inaugurou', 'inaugurar'], 'Le pont a été inauguré en 1966.', '« a ponte » est féminin au Portugal.'),
      C('« Ici on parle anglais » :', ['Aqui fala-se inglês.', 'Aqui se fala-se inglês.', 'Aqui a gente falam inglês.', 'Aqui fala-se em inglês-se.']),
      O('Il est interdit de fumer.', 'É proibido fumar', ['proíbe']),
      W('À vendre.', 'Vende-se'),
      L('Este mosteiro foi construído no século dezasseis.', 'Ce monastère a été construit au XVIe siècle.'),
      T('On recherche un serveur.', ['Precisa-se de empregado de mesa.', 'Procura-se-se um garçom.', 'Precisa-se um empregado de mesa de.', 'Busca-se garçom.'], '« garçom » est brésilien ; au Portugal : « empregado de mesa ».'),
    ]),

  lesson('Expressões idiomáticas', 'Expressions idiomatiques',
    G('Parler comme un Portugais',
      `<b>Fixe!</b> = Cool ! · <b>Giro/a</b> = joli, sympa · <b>Pois.</b> = Oui / C\'est vrai (le mot le plus portugais qui soit !) · <b>Bué</b> (Lisbonne, familier) = trop, très : bué fixe.<br><b>Custar os olhos da cara</b> = coûter les yeux de la tête · <b>Meter água</b> = faire une gaffe · <b>Estar com os azeites</b> = être de mauvaise humeur · <b>Ficar a ver navios</b> = rester le bec dans l\'eau · <b>Não há crise!</b> = Pas de souci ! · <b>Ir dar uma volta</b> = aller faire un tour.`,
      [['Este restaurante é bué fixe!', 'Ce restaurant est trop cool !'], ['O hotel custou os olhos da cara.', 'L\'hôtel a coûté les yeux de la tête.'], ['Hoje o chefe está com os azeites.', 'Aujourd\'hui le patron est de mauvaise humeur.']],
      '« Pois » peut tout dire : oui, en effet, eh bien… « Pois é! » = « C\'est clair ! ». « Pois não » = « Bien sûr ».'),
    [
      I('Fixe!', 'Cool ! / Génial !', 'Que fixe! Adorei.', 'Trop cool ! J\'ai adoré.'),
      I('Pois é', 'C\'est clair / En effet', 'Está calor, não está? — Pois é!', 'Il fait chaud, hein ? — Clairement !'),
      I('custar os olhos da cara', 'coûter les yeux de la tête', 'Os bilhetes custaram os olhos da cara.', 'Les billets ont coûté une fortune.'),
      I('meter água', 'faire une gaffe', 'Meti água na reunião.', 'J\'ai fait une gaffe en réunion.'),
      D('Na esplanada (en terrasse)', [
        ['Rita', 'Então, como foi o concerto?', 'Alors, c\'était comment le concert ?'],
        ['João', 'Bué fixe! Mas os bilhetes custaram os olhos da cara.', 'Trop cool ! Mais les billets ont coûté les yeux de la tête.'],
        ['Rita', 'Pois é… E o Pedro, foi convosco?', 'C\'est clair… Et Pedro, il est venu avec vous ?'],
        ['João', 'Não, meteu água: comprou bilhetes para o dia errado! Ficou a ver navios.', 'Non, il a fait une bourde : il a acheté des billets pour le mauvais jour ! Il est resté le bec dans l\'eau.'],
        ['Rita', 'Coitado! Deve estar com os azeites.', 'Le pauvre ! Il doit être de mauvaise humeur.'],
      ], [
        ['Qu\'a fait Pedro ?', ['Il a acheté des billets pour le mauvais jour', 'Il a perdu ses billets', 'Il était malade', 'Il a raté le train']],
        ['« Coitado! » signifie :', ['Le pauvre !', 'Quel idiot !', 'Tant mieux !', 'Bien fait !']],
      ]),
      F('Esse casaco custou os olhos da ___.', ['cara', 'cabeça', 'mão', 'boca'], 'Cette veste a coûté les yeux de la tête.'),
      F('Hoje ele está com os ___.', ['azeites', 'nervos de azeite', 'óleos', 'vinagres'], 'Aujourd\'hui il est de mauvaise humeur.'),
      C('« Meter água » signifie :', ['Faire une gaffe', 'Boire beaucoup', 'Pleuvoir', 'Aller nager']),
      O('Pas de souci !', 'Não há crise', ['tem']),
      W('Trop cool ! (Lisbonne, familier)', 'Bué fixe|Que fixe|Muito fixe|Fixe'),
      L('Pois é, ficámos a ver navios.', 'Eh oui, on est restés le bec dans l\'eau.'),
      T('On va faire un tour ?', ['Vamos dar uma volta?', 'Vamos fazer um tour?', 'Vamos dar um giro-se?', 'Vamos fazer uma volta de?']),
    ]),

  lesson('Falsos amigos', 'Les faux amis',
    G('Les faux amis portugais-français les plus traîtres',
      `<b>esquisito</b> = bizarre (≠ exquis → <i>requintado, delicioso</i>)<br><b>puxar</b> = TIRER (≠ pousser → <i>empurrar</i>) — attention aux portes !<br><b>o apelido</b> = le nom de famille (≠ surnom → <i>a alcunha</i>)<br><b>constipado</b> = enrhumé (≠ constipé)<br><b>acordar</b> = se réveiller (≠ accorder)<br><b>o talho</b> = la boucherie · <b>a prenda</b> = le cadeau · <b>a propina</b> = les frais de scolarité (≠ pourboire → <i>a gorjeta</i>)<br><b>largo</b> = large (≠ long → <i>comprido</i>)`,
      [['Que comida tão esquisita!', 'Quelle nourriture bizarre !'], ['Qual é o seu apelido?', 'Quel est votre nom de famille ?'], ['Acordei às sete.', 'Je me suis réveillé à sept heures.']],
      'Sur les portes : « PUXE » = TIREZ, « EMPURRE » = POUSSEZ. Le piège classique des Français au Portugal !'),
    [
      I('esquisito', 'bizarre', 'Que cheiro esquisito!', 'Quelle odeur bizarre !'),
      I('puxar / empurrar', 'tirer / pousser', 'Puxe a porta, não empurre!', 'Tirez la porte, ne poussez pas !'),
      I('o apelido', 'le nom de famille', 'O meu apelido é Martin.', 'Mon nom de famille est Martin.'),
      I('a prenda', 'le cadeau', 'Comprei uma prenda para a minha mãe.', 'J\'ai acheté un cadeau pour ma mère.'),
      D('No hotel', [
        ['Rececionista', 'Boa tarde. O seu nome, por favor?', 'Bonjour. Votre nom, s\'il vous plaît ?'],
        ['Rose', 'Rose. O apelido é Dubois.', 'Rose. Le nom de famille est Dubois.'],
        ['Rececionista', 'Obrigada. Está tudo bem? Parece cansada.', 'Merci. Tout va bien ? Vous avez l\'air fatiguée.'],
        ['Rose', 'Estou constipada, e acordei muito cedo. E a porta da entrada é esquisita: empurrei e não abria!', 'Je suis enrhumée, et je me suis réveillée très tôt. Et la porte d\'entrée est bizarre : j\'ai poussé et elle ne s\'ouvrait pas !'],
        ['Rececionista', 'Pois, é preciso puxar!', 'Eh oui, il faut tirer !'],
      ], [
        ['Quel est le « apelido » de Rose ?', ['Dubois', 'Rose', 'Son surnom', 'Son prénom']],
        ['Pourquoi la porte ne s\'ouvrait pas ?', ['Il fallait tirer', 'Elle était fermée à clé', 'Elle était cassée', 'Il fallait une carte']],
      ]),
      F('Para abrir a porta, tem de ___. (tirer)', ['puxar', 'empurrar', 'tirar', 'atirar'], 'Pour ouvrir la porte, il faut tirer.'),
      F('Deixámos uma boa ___ ao empregado.', ['gorjeta', 'propina', 'prenda', 'conta'], 'Nous avons laissé un bon pourboire au serveur.'),
      C('« Um sabor esquisito » =', ['un goût bizarre', 'un goût exquis', 'un goût sucré', 'un goût de poisson']),
      O('Mon nom de famille est Martin.', 'O meu apelido é Martin', ['alcunha']),
      W('Je me suis réveillé(e) tôt.', 'Acordei cedo|Eu acordei cedo'),
      L('Comprei uma prenda no talho? Não, no mercado!', 'J\'ai acheté un cadeau à la boucherie ? Non, au marché !'),
      T('Poussez !', ['Empurre!', 'Puxe!', 'Pouse!', 'Tire!']),
    ]),
]),

]);
})();
